mapper.select:
SELECT ss.*, es.subject_name, es.full_score, s.name AS student_name, s.student_number, c.name AS class_name FROM subject_score ss LEFT JOIN exam_subject es ON es.id = ss.exam_subject_id LEFT JOIN student s ON s.id = ss.student_id LEFT JOIN class_info c ON c.id = ss.class_id WHERE 1=1
AND ss.exam_id = #{query.examId}
AND ss.exam_subject_id = #{query.examSubjectId}
AND ss.class_id = #{query.classId}
AND s.name LIKE CONCAT('%', #{query.studentName}, '%')
AND s.student_number = #{query.studentNumber}
ORDER BY ss.score DESC, ss.grade_rank ASC
